class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Build initial graph: edge from i to i+1 for all i from 0 to n-2
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        result = []

        for u, v in queries:
            # Add the new edge
            graph[u].append(v)

            # Find shortest path from 0 to n-1 using BFS
            from collections import deque
            dist = [-1] * n
            dist[0] = 0
            queue = deque([0])

            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if dist[neighbor] == -1:
                        dist[neighbor] = dist[node] + 1
                        queue.append(neighbor)

            result.append(dist[n-1])

        return result

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 (top-left corner)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final row and column to position
        return row * n + col

class Solution:
    def countOfPairs(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # dp[i][j] = number of ways to assign arr1[0...i] such that arr1[i] = j
        # Use 1D array to save space
        prev_dp = [0] * (nums[0] + 1)

        # Initialize first position: arr1[0] can be any value from 0 to nums[0]
        for val in range(nums[0] + 1):
            prev_dp[val] = 1

        # Process each position from 1 to n-1
        for i in range(1, n):
            curr_dp = [0] * (nums[i] + 1)

            # For each possible value of arr1[i]
            for val in range(nums[i] + 1):
                # Determine minimum value that arr1[i] must have based on previous constraint
                # arr1[i] >= arr1[i-1] + (nums[i-1] - nums[i])
                # This is equivalent to arr1[i-1] <= arr1[i] - (nums[i-1] - nums[i])

                min_diff = nums[i-1] - nums[i]
                if min_diff > 0:
                    # We need arr1[i-1] <= val - min_diff
                    for prev_val in range(nums[i-1] + 1):
                        if prev_val <= val - min_diff:
                            curr_dp[val] = (curr_dp[val] + prev_dp[prev_val]) % MOD
                else:
                    # min_diff <= 0, so the constraint is automatically satisfied
                    # We just need arr1[i] >= arr1[i-1] (non-decreasing)
                    for prev_val in range(nums[i-1] + 1):
                        if prev_val <= val:
                            curr_dp[val] = (curr_dp[val] + prev_dp[prev_val]) % MOD

            prev_dp = curr_dp

        # Sum all possibilities for the last position
        result = 0
        for val in range(nums[n-1] + 1):
            result = (result + prev_dp[val]) % MOD

        return result

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store color counts for each player
        player_color_count = {}

        # Initialize for each player
        for i in range(n):
            player_color_count[i] = {}

        # Process each pick
        for player, color in pick:
            if color in player_color_count[player]:
                player_color_count[player][color] += 1
            else:
                player_color_count[player][color] = 1

        # Count how many players win
        winners = 0

        # Check each player from 0 to n-1
        for i in range(n):
            # Player i wins if they have at least (i+1) balls of the same color
            max_balls_of_same_color = 0
            for color, count in player_color_count[i].items():
                max_balls_of_same_color = max(max_balls_of_same_color, count)

            # Player i wins if max balls of same color >= i+1
            if max_balls_of_same_color >= i + 1:
                winners += 1

        return winners

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed to make all rows palindromic
        rows_flips = 0
        for i in range(m):
            for j in range(n // 2):
                if grid[i][j] != grid[i][n - 1 - j]:
                    rows_flips += 1

        # Calculate flips needed to make all columns palindromic
        cols_flips = 0
        for j in range(n):
            for i in range(m // 2):
                if grid[i][j] != grid[m - 1 - i][j]:
                    cols_flips += 1

        # Return minimum flips needed
        return min(rows_flips, cols_flips)
